from __future__ import annotations

import math

import torch

from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import StateIndex

# BBCoordsIndex of the reference: FL, RL, RR, FR, CENTER.
FRONT_LEFT = 0
REAR_LEFT = 1
REAR_RIGHT = 2
FRONT_RIGHT = 3
CENTER = 4
NUM_BB_COORDS = 5


def state_array_to_coords_torch(
    states: torch.Tensor,  # [..., 11]
    half_length: float,
    half_width: float,
    rear_axle_to_center: float,
) -> torch.Tensor:  # [..., 5, 2]
    """Ego bounding-box corners and center from state arrays.

    The lateral offset is written as ``cos(heading + pi/2)`` exactly like the
    reference's ``translate_lon_and_lat`` (mathematically ``-sin`` but not
    bitwise), so float64 agreement is at rounding level.
    """

    headings = states[..., StateIndex.HEADING]
    cos = torch.cos(headings)
    sin = torch.sin(headings)
    cos_lat = torch.cos(headings + math.pi / 2.0)
    sin_lat = torch.sin(headings + math.pi / 2.0)

    centers = states[..., :2] + torch.stack(
        [rear_axle_to_center * cos, rear_axle_to_center * sin], dim=-1
    )

    def _translate(lon: float, lat: float) -> torch.Tensor:
        return centers + torch.stack(
            [lat * cos_lat + lon * cos, lat * sin_lat + lon * sin], dim=-1
        )

    coords = torch.zeros(
        states.shape[:-1] + (NUM_BB_COORDS, 2),
        dtype=states.dtype,
        device=states.device,
    )
    coords[..., CENTER, :] = centers
    coords[..., FRONT_LEFT, :] = _translate(half_length, half_width)
    coords[..., FRONT_RIGHT, :] = _translate(half_length, -half_width)
    coords[..., REAR_LEFT, :] = _translate(-half_length, half_width)
    coords[..., REAR_RIGHT, :] = _translate(-half_length, -half_width)
    return coords


class TorchPolyline:
    """Arc-length projection onto a polyline (shapely ``project`` semantics).

    The nearest point over all segments wins; exact ties resolve to the first
    segment along the line, which is also GEOS's convention.  Zero-length
    segments project onto their start vertex.
    """

    def __init__(self, vertices: torch.Tensor, headings: torch.Tensor | None = None):  # [P, 2]
        if vertices.ndim != 2 or vertices.shape[-1] != 2 or vertices.shape[0] < 2:
            raise ValueError("polyline needs at least two 2-D vertices")
        self.vertices = vertices
        segments = torch.diff(vertices, dim=0)  # [P-1, 2]
        self._starts = vertices[:-1]
        self._segments = segments
        self._lengths_sq = (segments**2).sum(-1)  # [P-1]
        lengths = torch.sqrt(self._lengths_sq)
        self._cumulative = torch.nn.functional.pad(
            torch.cumsum(lengths, dim=0), (1, 0)
        )
        self._lengths = lengths
        if headings is None:
            raw = torch.atan2(segments[:, 1], segments[:, 0])
            headings = torch.cat((raw, raw[-1:]), dim=0)
            if headings.shape[0] > 1:
                delta = torch.atan2(
                    torch.sin(torch.diff(headings)),
                    torch.cos(torch.diff(headings)),
                )
                headings = torch.cat(
                    (headings[:1], headings[:1] + torch.cumsum(delta, dim=0)), dim=0
                )
        else:
            if headings.ndim != 1 or headings.shape[0] != vertices.shape[0]:
                raise ValueError("polyline headings must have shape [P]")
            headings = headings.to(device=vertices.device, dtype=vertices.dtype)
        self._headings = headings

    def project(self, points: torch.Tensor) -> torch.Tensor:  # [..., 2] -> [...]
        flat = points.reshape(-1, 2)  # [M, 2]
        offsets = flat[:, None, :] - self._starts[None, :, :]  # [M, S, 2]
        dots = (offsets * self._segments[None]).sum(-1)  # [M, S]
        fraction = torch.where(
            self._lengths_sq[None] > 0,
            (dots / self._lengths_sq[None].clamp(min=1e-300)).clamp(0.0, 1.0),
            torch.zeros_like(dots),
        )
        nearest = self._starts[None] + fraction[..., None] * self._segments[None]
        distance_sq = ((flat[:, None, :] - nearest) ** 2).sum(-1)  # [M, S]
        best = distance_sq.argmin(dim=1)  # first minimum wins
        rows = torch.arange(flat.shape[0], device=points.device)
        arc = self._cumulative[best] + fraction[rows, best] * self._lengths[best]
        return arc.reshape(points.shape[:-1])

    @property
    def length(self) -> torch.Tensor:
        """Total arc length as a scalar device tensor."""

        return self._cumulative[-1]

    @property
    def headings(self) -> torch.Tensor:
        """Unwrapped heading at every discrete vertex."""

        return self._headings

    def interpolate(self, distances: torch.Tensor) -> torch.Tensor:
        """Interpolate ``(x, y, heading)`` with ``PDMPath`` semantics."""

        values = torch.as_tensor(distances, device=self.vertices.device, dtype=self.vertices.dtype)
        clipped = values.clamp(min=1.0e-5, max=self.length)
        upper = torch.searchsorted(self._cumulative, clipped, right=False).clamp(
            min=1, max=self.vertices.shape[0] - 1
        )
        lower = upper - 1
        segment_length = self._lengths[lower]
        fraction = torch.where(
            segment_length > 0.0,
            (clipped - self._cumulative[lower]) / segment_length.clamp(min=1.0e-12),
            torch.zeros_like(clipped),
        )
        xy = self.vertices[lower] + fraction[..., None] * (
            self.vertices[upper] - self.vertices[lower]
        )
        heading = self._headings[lower] + fraction * (
            self._headings[upper] - self._headings[lower]
        )
        heading = torch.atan2(torch.sin(heading), torch.cos(heading))
        return torch.cat((xy, heading[..., None]), dim=-1)

    def parallel(self, offset: float | torch.Tensor) -> "TorchPolyline":
        """Return a lateral offset path without leaving the device."""

        offset_tensor = torch.as_tensor(offset, device=self.vertices.device, dtype=self.vertices.dtype)
        lateral = self._headings + math.pi / 2.0
        vertices = self.vertices + offset_tensor * torch.stack(
            (torch.cos(lateral), torch.sin(lateral)), dim=-1
        )
        return TorchPolyline(vertices, self._headings)


def raw_progress_torch(
    ego_centers: torch.Tensor,  # [N, T, 2] ego center coordinates over time
    centerline: TorchPolyline,
) -> torch.Tensor:  # [N]
    """``_calculate_progress``: arc-length gain of the center, clipped at 0."""

    endpoints = torch.stack([ego_centers[:, 0], ego_centers[:, -1]], dim=1)  # [N,2,2]
    arcs = centerline.project(endpoints)  # [N, 2]
    return (arcs[:, 1] - arcs[:, 0]).clamp(min=0.0)
